package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.Jsoup;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Tag;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_nextElementSibling_TriageGen1Test {

    private Document document;

    @Before
    public void setUp() {
        document = Jsoup.parse("<div><p>1</p><p>2</p><p>3</p><span>4</span></div>");
    }

    @Test
    public void testNextElementSibling_Exists() {
        Element p2 = document.select("p").get(1);
        Element expectedSibling = document.select("p").get(2);
        assertEquals(expectedSibling, p2.nextElementSibling());
    }

    @Test
    public void testNextElementSibling_NoNextSibling() {
        Element span = document.select("span").get(0);
        assertNull(span.nextElementSibling());
    }

    @Test
    public void testNextElementSibling_LastChild() {
        Element lastP = document.select("p").last();
        assertNull(lastP.nextElementSibling());
    }

    @Test
    public void testNextElementSibling_NoChildren() {
        Element div = document.select("div").get(0);
        div.empty();
        Element divChild = div.child(0);
        assertNull(divChild.nextElementSibling());
    }

    @Test
    public void testNextElementSibling_NullParent() {
        Element standaloneElement = new Element(Tag.valueOf("p"), "baseUri", new Attributes());
        assertNull(standaloneElement.nextElementSibling());
    }

    @Test
    public void testNextElementSibling_SingleChild() {
        Document singleChildDoc = Jsoup.parse("<div><p>only</p></div>");
        Element onlyChild = singleChildDoc.select("p").get(0);
        assertNull(onlyChild.nextElementSibling());
    }

    @Test
    public void testNextElementSibling_MixedChildren() {
        Document mixedDoc = Jsoup.parse("<div><p>1</p><span>2</span><p>3</p></div>");
        Element span = mixedDoc.select("span").get(0);
        Element expectedSibling = mixedDoc.select("p").get(2);
        assertEquals(expectedSibling, span.nextElementSibling());
    }
}
